import{_ as a,o as e,c as n,V as r}from"./chunks/framework.12adfae7.js";const _=JSON.parse('{"title":"qiankun 源码解析","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/coding-learning-record/qiankun.md","filePath":"blogs/coding-learning-record/qiankun.md"}'),o={name:"blogs/coding-learning-record/qiankun.md"},t=r('<h1 id="qiankun-源码解析" tabindex="-1">qiankun 源码解析 <a class="header-anchor" href="#qiankun-源码解析" aria-label="Permalink to &quot;qiankun 源码解析&quot;">​</a></h1><h2 id="css隔离" tabindex="-1">css隔离 <a class="header-anchor" href="#css隔离" aria-label="Permalink to &quot;css隔离&quot;">​</a></h2><p>实现子应用之间的样式隔离</p><p>experimentalStyleIsolation</p><p>shadow dom</p><p>主应用影响子应用的类名 用scoped解决</p><h2 id="js隔离" tabindex="-1">js隔离 <a class="header-anchor" href="#js隔离" aria-label="Permalink to &quot;js隔离&quot;">​</a></h2><p>SnapshotSandbox</p><p>ProxySandbox</p><p>app 环境沙箱 app 环境沙箱是指应用初始化过之后，应用会在什么样的上下文环境运行。每个应用的环境沙箱只会初始化一次，因为子应用只会触发一次 bootstrap 。子应用在切换时，实际上切换的是 app 环境沙箱。 render 沙箱 子应用在 app mount 开始前生成好的的沙箱。每次子应用切换过后，render 沙箱都会重新初始化。</p><h2 id="子应用加载方式" tabindex="-1">子应用加载方式 <a class="header-anchor" href="#子应用加载方式" aria-label="Permalink to &quot;子应用加载方式&quot;">​</a></h2><p>无界获取子应用的脚本采用的是qiankun的import-html-entry方案，这个方案是通过正则表达式将 子应用的 html 按照顺序拿出来，然后用fetch 请求回来，按照顺序内联在子应用里面运行</p><h2 id="乾坤子应用keepalive" tabindex="-1">乾坤子应用keepalive <a class="header-anchor" href="#乾坤子应用keepalive" aria-label="Permalink to &quot;乾坤子应用keepalive&quot;">​</a></h2><h2 id="缓存场景下-css加载404异常捕捉不到的问题" tabindex="-1">缓存场景下 css加载404异常捕捉不到的问题 <a class="header-anchor" href="#缓存场景下-css加载404异常捕捉不到的问题" aria-label="Permalink to &quot;缓存场景下 css加载404异常捕捉不到的问题&quot;">​</a></h2><p>思路： debug 进一步定位抛错位置 尝试捕获到之后重试</p><h2 id="状态管理" tabindex="-1">状态管理 <a class="header-anchor" href="#状态管理" aria-label="Permalink to &quot;状态管理&quot;">​</a></h2><p>qiankun 提供了集中式的状态管理方案，它通过 props 和全局状态对象来实现子应用之间的通信和状态共享。</p><p>singleSPA 则更加灵活，它并没有内置的状态管理功能，而是鼓励开发者使用其他流行的状态管理库（如 Redux、Vuex 等）来处理子应用之间的数据共享。</p><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2>',19),i=[t];function s(l,d,p,c,h,u){return e(),n("div",null,i)}const k=a(o,[["render",s]]);export{_ as __pageData,k as default};
